type Task = {
  id: string;
  title: string;
  notes: string;
  status: Status;
  priority: Priority;
  dueDate: string;
  createdAt: string;
};

type Prefs = {
  theme: Theme;
  status: "all" | Status;
  priority: "all" | Priority;
  sort: "newest" | "due" | "priority";
};

const TASKS_KEY = "task-manager.tasks";
const PREFS_KEY = "task-manager.prefs";

const defaultPrefs: Prefs = { theme: "system", status: "all", priority: "all", sort: "newest" };
const seedTasks: Task[] = [
  {
    id: "seed-1",
    title: "Plan weekly priorities",
    notes: "Review backlog and pick the top three outcomes.",
    status: "todo",
    priority: "high",
    dueDate: new Date().toISOString().slice(0, 10),
    createdAt: new Date().toISOString(),
  },
];

const emptyTask = (): Task => ({
  id: "",
  title: "",
  notes: "",
  status: "todo",
  priority: "medium",
  dueDate: "",
  createdAt: "",
});

function uid() {
  return typeof crypto !== "undefined" && "randomUUID" in crypto
    ? crypto.randomUUID()
    : Math.random().toString(36).slice(2);
}

function parseStatus(value: string): Status | null {
  switch (value) {
    case "todo":
      return "todo";
    case "doing":
      return "doing";
    case "done":
      return "done";
    default:
      return null;
  }
}

function parsePriority(value: string): Priority | null {
  switch (value) {
    case "low":
      return "low";
    case "medium":
      return "medium";
    case "high":
      return "high";
    default:
      return null;
  }
}

function parseTheme(value: string): Theme | null {
  switch (value) {
    case "light":
      return "light";
    case "dark":
      return "dark";
    case "system":
      return "system";
    default:
      return null;
  }
}

function parseStatusFilter(value: string): Prefs["status"] | null {
  if (value === "all") {
    return "all";
  }

  return parseStatus(value);
}

function parsePriorityFilter(value: string): Prefs["priority"] | null {
  if (value === "all") {
    return "all";
  }

  return parsePriority(value);
}

function parseSort(value: string): Prefs["sort"] | null {
  switch (value) {
    case "newest":
      return "newest";
    case "due":
      return "due";
    case "priority":
      return "priority";
    default:
      return null;
  }
}

function Modal({
  title,
  children,
