'use client';

import { X } from 'lucide-react';
import { useEffect, useMemo, useState } from 'react';

type Status = 'all' | 'open' | 'done';
type Theme = 'light' | 'dark';

type Task = {
  id: string;
  title: string;
  notes: string;
  done: boolean;
  createdAt: number;
};

type ModalState =
  | { mode: 'create'; task: null }
  | { mode: 'edit'; task: Task }
  | null;

type Prefs = {
  theme: Theme;
  compact: boolean;
  status: Status;
};

const TASKS_KEY = 'tm.tasks';
const PREFS_KEY = 'tm.prefs';

function uid() {
  return Math.random().toString(36).slice(2, 10);
}

function isStatus(value: unknown): value is Status {
  return value === 'all' || value === 'open' || value === 'done';
}

function isTheme(value: unknown): value is Theme {
  return value === 'light' || value === 'dark';
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null;
}

function isTask(value: unknown): value is Task {
  if (!isRecord(value)) return false;
  return (
    typeof value.id === 'string' &&
    typeof value.title === 'string' &&
    typeof value.notes === 'string' &&
    typeof value.done === 'boolean' &&
    typeof value.createdAt === 'number'
  );
}

function isTaskArray(value: unknown): value is Task[] {
  return Array.isArray(value) && value.every(isTask);
}

function isPrefs(value: unknown): value is Prefs {
  if (!isRecord(value)) return false;
  return (
    isTheme(value.theme) &&
    typeof value.compact === 'boolean' &&
    isStatus(value.status)
  );
}

function getStatusFromValue(value: string): Status {
  if (isStatus(value)) {
    return value;
  }
  console.warn('Invalid status selection, defaulting to "all":', value);
  return 'all';
}

function Modal({
  open,
  title,
  children,
  onClose,
}: {
  open: boolean;
  title: string;
  children: React.ReactNode;
  onClose: () => void;
}) {
  if (!open) return null;
  return (
    <div className="fixed inset-0 z-50 grid place-items-center bg-black/50 p-4" onClick={onClose}>
      <div
        className="w-full max-w-lg rounded-2xl border border-black/10 bg-white p-5 shadow-2xl dark:border-white/10 dark:bg-zinc-900"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="mb-4 flex items-center justify-between">
          <h2 className="text-lg font-semibold">{title}</h2>
          <button
            className="rounded-md px-2 py-1 text-sm hover:bg-black/5 dark:hover:bg-white/10"
            onClick={onClose}
            aria-label="Close modal"
          >
            <X className="h-4 w-4" />
          </button>
        </div>
        {children}
      </div>
    </div>
  );
}

