"use client";

import { useState, useEffect, useCallback } from "react";
import { Sun, Moon } from "lucide-react";

type Priority = "low" | "medium" | "high";
type Status = "todo" | "in-progress" | "done";
interface Task { id: string; title: string; description: string; priority: Priority; status: Status; createdAt: number; }
interface ModalState { open: boolean; task: Task | null; }

const STORAGE_KEY = "tasks_v1";
const PREFS_KEY = "ui_prefs_v1";
const uid = () => Math.random().toString(36).slice(2);

const priorityColorClass: Record<Priority, string> = {
  low: "bg-green-500",
  medium: "bg-amber-500",
  high: "bg-red-500",
};

const priorityBadgeClass: Record<Priority, string> = {
  low: "bg-green-500/20 text-green-500",
  medium: "bg-amber-500/20 text-amber-500",
  high: "bg-red-500/20 text-red-500",
};

function isStatus(value: string): value is Status {
  return value === "todo" || value === "in-progress" || value === "done";
}

function isPriority(value: string): value is Priority {
  return value === "low" || value === "medium" || value === "high";
}

function isStatusOrAll(value: string): value is Status | "all" {
  return value === "all" || isStatus(value);
}

function isPriorityOrAll(value: string): value is Priority | "all" {
  return value === "all" || isPriority(value);
}

function isRecordObject(item: unknown): item is Record<string, unknown> {
  return item !== null && typeof item === "object" && !Array.isArray(item);
}

function parseStoredTasks(raw: string): Task[] {
  try {
    const parsed: unknown = JSON.parse(raw);
    if (Array.isArray(parsed)) {
      return parsed.filter((item): item is Task => {
        if (!isRecordObject(item)) return false;
        return (
          typeof item.id === "string" &&
          typeof item.title === "string" &&
          typeof item.description === "string" &&
          isPriority(String(item.priority)) &&
          isStatus(String(item.status)) &&
          typeof item.createdAt === "number"
        );
      });
    }
    console.warn("Stored tasks is not an array, resetting to empty.");
    return [];
  } catch {
    return [];
  }
}

function parseStoredPrefs(raw: string): { dark: boolean | null } {
  try {
    const parsed: unknown = JSON.parse(raw);
    if (isRecordObject(parsed)) {
      return { dark: typeof parsed.dark === "boolean" ? parsed.dark : null };
    }
    console.warn("Stored prefs is not an object, using defaults.");
    return { dark: null };
  } catch {
    return { dark: null };
  }
}

export default function Page() {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [search, setSearch] = useState("");
  const [filterStatus, setFilterStatus] = useState<Status | "all">("all");
  const [filterPriority, setFilterPriority] = useState<Priority | "all">("all");
  const [dark, setDark] = useState(false);
  const [modal, setModal] = useState<ModalState>({ open: false, task: null });
  const [form, setForm] = useState<{ title: string; description: string; priority: Priority; status: Status }>({ title: "", description: "", priority: "medium", status: "todo" });

  useEffect(() => {
    setTasks(parseStoredTasks(localStorage.getItem(STORAGE_KEY) || "[]"));
    const prefs = parseStoredPrefs(localStorage.getItem(PREFS_KEY) || "{}");
    setDark(prefs.dark === true);
  }, []);

  useEffect(() => { localStorage.setItem(STORAGE_KEY, JSON.stringify(tasks)); }, [tasks]);
  useEffect(() => {
    localStorage.setItem(PREFS_KEY, JSON.stringify({ dark }));
    document.body.classList.toggle("bg-gray-900", dark);
    document.body.classList.toggle("bg-slate-50", !dark);
  }, [dark]);

  const openCreate = () => { setForm({ title: "", description: "", priority: "medium", status: "todo" }); setModal({ open: true, task: null }); };
