"use client";

import { useState, useEffect, useMemo, useCallback } from "react";
import { Moon, Sun, Pencil, Trash2 } from "lucide-react";

type Task = {
  id: string;
  title: string;
  description: string;
  status: "todo" | "in-progress" | "done";
  createdAt: number;
};

type Theme = "light" | "dark";
type FilterStatus = "all" | Task["status"];

const STORAGE_TASKS = "tm_tasks";
const STORAGE_PREFS = "tm_prefs";

function uid() {
  return Math.random().toString(36).slice(2, 10) + Date.now().toString(36);
}

function isTheme(value: unknown): value is Theme {
  return value === "light" || value === "dark";
}

function isTaskArray(value: unknown): value is Task[] {
  return Array.isArray(value);
}

function isPrefsObject(value: unknown): value is { theme: Theme } {
  if (typeof value === "object" && value !== null && "theme" in value) {
    const obj = value as Record<string, unknown>;
    return isTheme(obj.theme);
  }
  return false;
}

function loadTasks(): Task[] {
  if (typeof window === "undefined") return [];
  try {
    const raw = localStorage.getItem(STORAGE_TASKS);
    if (raw !== null) {
      const parsed: unknown = JSON.parse(raw);
      if (isTaskArray(parsed)) {
        return parsed;
      }
      console.warn("Stored tasks data is not a valid array, using fallback.");
      return [];
    }
    return [];
  } catch {
    return [];
  }
}

function loadTheme(): Theme {
  if (typeof window === "undefined") return "light";
  try {
    const raw = localStorage.getItem(STORAGE_PREFS);
    if (raw !== null) {
      const parsed: unknown = JSON.parse(raw);
      if (isPrefsObject(parsed)) {
        return parsed.theme;
      }
      console.warn("Stored prefs data is not valid, using fallback.");
      return "light";
    }
    return "light";
  } catch {
    return "light";
  }
}

function saveJSON({ key, value }: { key: string; value: unknown }) {
  if (typeof window !== "undefined" && typeof localStorage !== "undefined") {
    localStorage.setItem(key, JSON.stringify(value));
  } else {
    console.warn("localStorage is not available; skipping save for key:", key);
  }
}

const statusLabels: Record<Task["status"], string> = {
  todo: "To Do",
  "in-progress": "In Progress",
  done: "Done",
};

const statusKeys: Task["status"][] = ["todo", "in-progress", "done"];

function isTaskStatus(value: unknown): value is Task["status"] {
  return value === "todo" || value === "in-progress" || value === "done";
}

function isFilterStatus(value: unknown): value is FilterStatus {
  return value === "all" || isTaskStatus(value);
}

export default function Page() {
  const [tasks, setTasks] = useState<Task[]>([]);
  const [theme, setTheme] = useState<Theme>("light");
  const [search, setSearch] = useState("");
  const [filter, setFilter] = useState<FilterStatus>("all");
  const [modalOpen, setModalOpen] = useState(false);
