    if (!hydrated) {
      return;
    }
    saveJSON({ key: STORAGE_PREFS, value: { theme } });
  }, [theme, hydrated]);

  const filtered = useMemo(() => {
    let list = tasks;
    if (filter !== "all") {
      list = list.filter((t) => t.status === filter);
