        typingTimers.current.forEach(clearTimeout);
        typingTimers.current.clear();
      };
    };

    return user ? subscribeToRoom(user) : logMissingUser();
  }, [supabase, user]);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth", block: "end" });
  }, [messages, typingUsers]);

  const broadcastTyping = useCallback(
    (typing: boolean) => {
      const channel = typingChannel.current;

      channel && user
        ? void channel.send({
            type: "broadcast",
            event: "typing",
            payload: { userId: user.id, name, typing },
          })
        : console.debug("Skipped typing broadcast because channel or user is unavailable.");
    },
    [name, user],
  );

  const onDraftChange = (value: string) => {
    setDraft(value);
    const now = Date.now();
    const shouldBroadcastTyping = Boolean(value.trim()) && now - lastTypingAt.current > 1200;

    shouldBroadcastTyping
      ? (() => {
          lastTypingAt.current = now;
          broadcastTyping(true);
        })()
      : console.debug("Skipped start-typing broadcast because the draft is empty or throttled.");

    stopTypingTimer.current
      ? clearTimeout(stopTypingTimer.current)
      : console.debug("No previous stop-typing timer existed.");

    stopTypingTimer.current = setTimeout(() => broadcastTyping(false), 1600);
  };

  const submitMessage = async ({
    content,
    currentUser,
  }: {
    content: string;
    currentUser: User;
  }) => {
    setSending(true);
    setError(null);
    broadcastTyping(false);

    const { data, error } = await supabase
      .from("messages")
      .insert({ room_id: ROOM_ID, user_id: currentUser.id, username: name, content })
      .select("id, room_id, user_id, username, content, created_at")
      .single();

    setSending(false);

    if (error) {
      setError(error.message);
    } else {
