'use client';

import { useEffect, useMemo, useRef, useState } from 'react';
import Link from 'next/link';
import { useQuery } from '@tanstack/react-query';

type User = { id: string; name: string; email: string };
type Message = { id: string; userId: string; userName: string; text: string; createdAt: string };
type TypingState = Record<string, string>;

const DRAFT_KEY = 'chat:draft';
const THEME_KEY = 'chat:theme';

function uid() {
  return Math.random().toString(36).slice(2, 10);
}

function timeLabel(iso: string) {
  return new Date(iso).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
}

function isUser(value: unknown): value is User {
  if (typeof value !== 'object' || value === null) return false;
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.id === 'string' &&
    typeof candidate.name === 'string' &&
    typeof candidate.email === 'string'
  );
}

function isMessage(value: unknown): value is Message {
  if (typeof value !== 'object' || value === null) return false;
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate.id === 'string' &&
    typeof candidate.userId === 'string' &&
    typeof candidate.userName === 'string' &&
    typeof candidate.text === 'string' &&
    typeof candidate.createdAt === 'string'
  );
}

function isMessageArray(value: unknown): value is Message[] {
  return Array.isArray(value) && value.every(isMessage);
}

type WsMessage =
  | { type: 'message'; payload: Message }
  | { type: 'typing'; payload: { userId: string; userName: string; isTyping: boolean } };

function isWsMessage(value: unknown): value is WsMessage {
  if (typeof value !== 'object' || value === null) return false;
  const candidate = value as Record<string, unknown>;
  if (candidate.type === 'message') {
    return isMessage(candidate.payload);
  }
  if (candidate.type === 'typing') {
    if (typeof candidate.payload !== 'object' || candidate.payload === null) return false;
    const payload = candidate.payload as Record<string, unknown>;
    return (
      typeof payload.userId === 'string' &&
      typeof payload.userName === 'string' &&
      typeof payload.isTyping === 'boolean'
    );
  }
  return false;
}

export default function Page() {
  const [user, setUser] = useState<User | null>(null);
  const [checkingAuth, setCheckingAuth] = useState(true);
  const [messages, setMessages] = useState<Message[]>([]);
  const [typing, setTyping] = useState<TypingState>({});
  const [text, setText] = useState('');
  const [theme, setTheme] = useState<'light' | 'dark'>('light');
  const [wsUrl, setWsUrl] = useState<string | null>(null);
  const listRef = useRef<HTMLDivElement>(null);
  const socketRef = useRef<WebSocket | null>(null);
  const typingTimer = useRef<number | null>(null);

  useEffect(() => {
    if (typeof window !== 'undefined') {
      const savedTheme = window.localStorage.getItem(THEME_KEY);
      const nextTheme = savedTheme === 'dark' ? 'dark' : 'light';
      setTheme(nextTheme);
      document.documentElement.classList.toggle('dark', nextTheme === 'dark');
      setText(window.localStorage.getItem(DRAFT_KEY) || '');

      const protocol = window.location.protocol === 'https:' ? 'wss' : 'ws';
      setWsUrl(`${protocol}://${window.location.host}/api/chat/ws`);
    } else {
      console.warn('Window is unavailable during initial render; skipping local theme, draft, and websocket URL setup.');
    }

    let cancelled = false;
    (async () => {
      try {
        const res = await fetch('/api/auth/me', { credentials: 'include' });
        if (!res.ok) throw new Error('unauthorized');

        const data: unknown = await res.json();
        if (isUser(data)) {
          if (!cancelled) setUser(data);
        } else {
          console.error('Received invalid auth payload.', data);
          if (!cancelled) setUser(null);
        }
      } catch (error) {
        console.error('Failed to load authenticated user.', error);
        if (!cancelled) setUser(null);
      } finally {
        if (!cancelled) setCheckingAuth(false);
      }
    })();

    return () => {
      cancelled = true;
      socketRef.current?.close();
      if (typingTimer.current !== null) {
        window.clearTimeout(typingTimer.current);
      } else {
        console.warn('No typing timeout to clear during cleanup.');
      }
    };
  }, []);

  const messagesQuery = useQuery({
    queryKey: ['chat-messages'],
    queryFn: async () => {
      const res = await fetch('/api/chat/messages', { cache: 'no-store' });
      if (!res.ok) {
        throw new Error('Failed to fetch messages');
      }
      const data: unknown = await res.json();
      if (!isMessageArray(data)) {
        throw new Error('Invalid messages payload');
      }
      return data;
    },
    enabled: Boolean(user),
    staleTime: 0,
  });

  useEffect(() => {
    if (messagesQuery.data) {
      setMessages(messagesQuery.data);
    } else if (messagesQuery.isError) {
      console.error('Unable to hydrate message history from query.', messagesQuery.error);
    } else {
      console.warn('Message history is not available yet.');
    }
  }, [messagesQuery.data, messagesQuery.error, messagesQuery.isError]);

  useEffect(() => {
    if (!user) {
      console.warn('Skipping websocket connection because there is no authenticated user.');
      return;
    }
    if (!wsUrl) {
      console.warn('Skipping websocket connection because websocket URL is not available yet.');
      return;
    }

    const ws = new WebSocket(wsUrl);
    socketRef.current = ws;

    ws.onmessage = (event) => {
      try {
        const raw: unknown = JSON.parse(event.data);
        if (!isWsMessage(raw)) {
          console.error('Received invalid websocket payload.', raw);
          return;
        }

        if (raw.type === 'message') {
          setMessages((prev) => [...prev, raw.payload]);
        } else if (raw.type === 'typing') {
          setTyping((prev) => {
            const next = { ...prev };
            if (raw.payload.isTyping) {
              next[raw.payload.userId] = raw.payload.userName;
            } else {
              delete next[raw.payload.userId];
            }
            return next;
          });
        } else {
          console.warn('Received websocket message with unsupported type.', raw);
        }
      } catch (error) {
        console.error('Failed to parse websocket message.', error);
      }
    };

    return () => {
      ws.close();
    };
  }, [user, wsUrl]);

  useEffect(() => {
    if (typeof window !== 'undefined') {
      window.localStorage.setItem(DRAFT_KEY, text);
    } else {
      console.warn('Window is unavailable; draft was not persisted.');
    }
  }, [text]);

  useEffect(() => {
    document.documentElement.classList.toggle('dark', theme === 'dark');
    if (typeof window !== 'undefined') {
      window.localStorage.setItem(THEME_KEY, theme);
    } else {
      console.warn('Window is unavailable; theme was not persisted.');
    }
  }, [theme]);

  useEffect(() => {
    if (listRef.current) {
