type User = { id: string; name: string; email: string };
type Message = { id: string; userId: string; userName: string; text: string; createdAt: string };
type TypingState = Record<string, string>;

const DRAFT_KEY = 'chat:draft';
const THEME_KEY = 'chat:theme';

function uid() {
  return Math.random().toString(36).slice(2, 10);
}

function timeLabel(iso: string) {
  return new Date(iso).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null;
}

function isUser(value: unknown): value is User {
  if (!isRecord(value)) return false;
  return (
    typeof value.id === 'string' &&
    typeof value.name === 'string' &&
    typeof value.email === 'string'
  );
}

function isMessage(value: unknown): value is Message {
  if (!isRecord(value)) return false;
  return (
    typeof value.id === 'string' &&
    typeof value.userId === 'string' &&
    typeof value.userName === 'string' &&
    typeof value.text === 'string' &&
    typeof value.createdAt === 'string'
  );
}

function isMessageArray(value: unknown): value is Message[] {
  return Array.isArray(value) && value.every(isMessage);
}

type WsMessage =
  | { type: 'message'; payload: Message }
  | { type: 'typing'; payload: { userId: string; userName: string; isTyping: boolean } };

function isWsMessage(value: unknown): value is WsMessage {
  if (!isRecord(value)) return false;
  if (value.type === 'message') {
    return isMessage(value.payload);
  }
  if (value.type === 'typing') {
    if (!isRecord(value.payload)) return false;
    return (
      typeof value.payload.userId === 'string' &&
      typeof value.payload.userName === 'string' &&
      typeof value.payload.isTyping === 'boolean'
    );
  }
  return false;
}

export default function Page() {
