    if (typeof window !== 'undefined') {
      const savedTheme = window.localStorage.getItem(THEME_KEY);
      const nextTheme = savedTheme === 'dark' ? 'dark' : 'light';
      setTheme(nextTheme);
      document.documentElement.classList.toggle('dark', nextTheme === 'dark');
      setText(window.localStorage.getItem(DRAFT_KEY) || '');

      const protocol = window.location.protocol === 'https:' ? 'wss' : 'ws';
      setWsUrl(`${protocol}://${window.location.host}/api/chat/ws`);
    } else {
      console.warn('Window is unavailable during initial render; skipping local theme, draft, and websocket URL setup.');
    }

    let cancelled = false;
    (async () => {
      try {
        const res = await fetch('/api/auth/me', { credentials: 'include' });
        if (!res.ok) throw new Error('unauthorized');

        const data: unknown = await res.json();
        if (isUser(data)) {
          if (!cancelled) {
            setUser(data);
          } else {
            console.warn('Auth payload was valid, but state update was skipped because the effect was cancelled.');
          }
        } else {
          console.error('Received invalid auth payload.', data);
          if (!cancelled) {
            setUser(null);
          } else {
            console.warn('Invalid auth payload handling skipped because the effect was cancelled.');
          }
        }
      } catch (error) {
        console.error('Failed to load authenticated user.', error);
        Sentry.captureException(error);
        if (!cancelled) {
          setUser(null);
        } else {
          console.warn('Failed auth state update was skipped because the effect was cancelled.');
        }
      } finally {
        if (!cancelled) {
          setCheckingAuth(false);
        } else {
          console.warn('Auth loading completion update was skipped because the effect was cancelled.');
        }
      }
    })();

    return () => {
      cancelled = true;
      socketRef.current?.close();
