"use client";

import { useState, useEffect, useRef, useCallback } from "react";
import { Sun, Moon, MessageCircle, LogOut, Send } from "lucide-react";
import * as Sentry from "@sentry/nextjs";

type Message = { id: string; user: string; text: string; ts: number };
type Theme = "light" | "dark";

const STORAGE_DRAFT = "chat_draft";
const STORAGE_USER = "chat_user";
const STORAGE_MSGS = "chat_messages";

function uid() {
  return Math.random().toString(36).slice(2, 10);
}

function formatTime(ts: number) {
  return new Date(ts).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
}

export default function ChatPage() {
  const [theme, setTheme] = useState<Theme>("light");
  const [username, setUsername] = useState("");
  const [nameInput, setNameInput] = useState("");
  const [messages, setMessages] = useState<Message[]>([]);
  const [draft, setDraft] = useState("");
  const [typingUsers, setTypingUsers] = useState<string[]>([]);
  const bottomRef = useRef<HTMLDivElement>(null);
  const typingTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const isTypingRef = useRef(false);

  useEffect(() => {
    const saved = localStorage.getItem(STORAGE_USER);
    if (saved) {
      setUsername(saved);
    } else {
      console.debug("[ChatPage] No saved username found");
    }

    const savedMsgs = localStorage.getItem(STORAGE_MSGS);
    if (savedMsgs) {
      try {
        setMessages(JSON.parse(savedMsgs));
      } catch (err) {
        console.error("[ChatPage] Failed to parse saved messages:", err);
        Sentry.captureException(err);
      }
    } else {
      console.debug("[ChatPage] No saved messages found");
    }

    const savedDraft = localStorage.getItem(STORAGE_DRAFT);
    if (savedDraft) {
      setDraft(savedDraft);
    } else {
      console.debug("[ChatPage] No saved draft found");
    }
  }, []);

  useEffect(() => {
    document.documentElement.setAttribute("data-theme", theme);
  }, [theme]);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages, typingUsers]);

  useEffect(() => {
    if (!username) {
      console.debug("[ChatPage] No username set, skipping draft persistence");
      return;
    }
    localStorage.setItem(STORAGE_DRAFT, draft);
  }, [draft, username]);

  const simulateIncoming = useCallback((sentText: string) => {
    const bot = "Bot";
    setTypingUsers((p) => [...p, bot]);
    setTimeout(() => {
      setTypingUsers((p) => p.filter((u) => u !== bot));
      const reply: Message = {
        id: uid(),
        user: bot,
        text: `Echo: ${sentText}`,
        ts: Date.now(),
      };
      setMessages((prev) => {
        const next = [...prev, reply];
        localStorage.setItem(STORAGE_MSGS, JSON.stringify(next));
        return next;
      });
    }, 1400);
  }, []);

  const sendMessage = useCallback(() => {
    const text = draft.trim();
    if (!text) {
      console.debug("[ChatPage] sendMessage called with empty draft, skipping");
      return;
    }
    const msg: Message = { id: uid(), user: username, text, ts: Date.now() };
    setMessages((prev) => {
      const next = [...prev, msg];
      localStorage.setItem(STORAGE_MSGS, JSON.stringify(next));
      return next;
    });
    setDraft("");
    localStorage.removeItem(STORAGE_DRAFT);
    simulateIncoming(text);
  }, [draft, username, simulateIncoming]);

  const handleDraftChange = (val: string) => {
    setDraft(val);
    if (!isTypingRef.current) {
      isTypingRef.current = true;
      setTypingUsers((p) => (p.includes(username) ? p : [...p, username]));
    } else {
      console.debug("[ChatPage] Already marked as typing");
    }
    if (typingTimer.current) {
      clearTimeout(typingTimer.current);
    } else {
      console.debug("[ChatPage] No existing typing timer to clear");
    }
    typingTimer.current = setTimeout(() => {
      isTypingRef.current = false;
      setTypingUsers((p) => p.filter((u) => u !== username));
    }, 1200);
  };

  const login = () => {
    const name = nameInput.trim();
    if (!name) {
      console.debug("[ChatPage] login called with empty name, skipping");
      return;
    }
    setUsername(name);
    localStorage.setItem(STORAGE_USER, name);
  };

  const logout = () => {
    setUsername("");
    localStorage.removeItem(STORAGE_USER);
  };

  const isDark = theme === "dark";

  if (!username) {
    return (
      <div className={`flex items-center justify-center min-h-screen ${isDark ? "bg-[#1a1a2e]" : "bg-[#f0f4f8]"}`}>
        <div className={`${isDark ? "bg-[#16213e]" : "bg-white"} p-10 rounded-2xl shadow-lg min-w-[320px]`}>
          <h2 className={`${isDark ? "text-[#e0e0e0]" : "text-[#1a1a2e]"} mb-5 text-center text-xl font-bold`}>
            Join Chat
          </h2>
          <input
            autoFocus
            placeholder="Your name"
            value={nameInput}
            onChange={(e) => setNameInput(e.target.value)}
            onKeyDown={(e) => e.key === "Enter" && login()}
            className={`w-full px-4 py-2.5 rounded-lg border border-gray-300 text-sm mb-3.5 box-border ${isDark ? "bg-[#1a1a2e] text-[#e0e0e0]" : "bg-white text-[#1a1a2e]"} focus:outline-none`}
          />
          <button
            onClick={login}
            className="w-full py-2.5 bg-[#4f8ef7] text-white border-none rounded-lg text-sm cursor-pointer hover:bg-[#3a7de6] transition-colors"
          >
            Enter
          </button>
        </div>
      </div>
    );
  }

  const otherTypingUsers = typingUsers.filter((u) => u !== username);

  return (
    <div className={`flex flex-col h-screen ${isDark ? "bg-[#1a1a2e] text-[#e0e0e0]" : "bg-[#f0f4f8] text-[#1a1a2e]"} font-sans`}>
      <header className={`${isDark ? "bg-[#16213e]" : "bg-white"} px-5 py-3 flex items-center justify-between shadow-sm`}>
        <span className="font-bold text-lg flex items-center gap-2">
          <MessageCircle size={20} className="text-[#4f8ef7]" />
          Realtime Chat
        </span>
        <div className="flex gap-2.5 items-center">
          <span className="text-xs opacity-70">Hi, {username}</span>
          <button
            onClick={() => setTheme((t) => (t === "dark" ? "light" : "dark"))}
            className={`flex items-center gap-1 bg-transparent border border-gray-400 rounded-lg px-2.5 py-1 cursor-pointer ${isDark ? "text-[#e0e0e0]" : "text-[#1a1a2e]"} text-xs hover:opacity-80 transition-opacity`}
          >
            {isDark ? <Sun size={14} /> : <Moon size={14} />}
            {isDark ? "Light" : "Dark"}
          </button>
          <button
            onClick={logout}
            className={`flex items-center gap-1 bg-transparent border border-gray-400 rounded-lg px-2.5 py-1 cursor-pointer ${isDark ? "text-[#e0e0e0]" : "text-[#1a1a2e]"} text-xs hover:opacity-80 transition-opacity`}
          >
            <LogOut size={14} />
            Logout
          </button>
        </div>
      </header>

      <div className="flex-1 overflow-y-auto px-4 py-5 flex flex-col gap-2.5">
        {messages.length === 0 && (
          <p className="text-center opacity-40 mt-10">No messages yet. Say hello!</p>
        )}
        {messages.map((m) => {
          const self = m.user === username;
          return (
            <div
              key={m.id}
              className={`flex flex-col ${self ? "items-end" : "items-start"}`}
            >
              <span className="text-[11px] opacity-50 mb-0.5">
                {m.user} · {formatTime(m.ts)}
              </span>
              <div
                className={`px-3.5 py-2 rounded-2xl max-w-[70%] text-sm leading-relaxed break-words ${
                  self
                    ? "bg-[#4f8ef7] text-white rounded-br-sm"
                    : isDark
                    ? "bg-[#2a2a4a] text-[#e0e0e0] rounded-bl-sm"
                    : "bg-[#e2e8f0] text-[#1a1a2e] rounded-bl-sm"
                }`}
              >
                {m.text}
              </div>
            </div>
          );
        })}
        {otherTypingUsers.length > 0 && (
          <div className="text-xs opacity-55 italic">
            {otherTypingUsers.join(", ")}{" "}
            {otherTypingUsers.length === 1 ? "is" : "are"} typing…
          </div>
        )}
        <div ref={bottomRef} />
      </div>

      <div className={`${isDark ? "bg-[#16213e]" : "bg-white"} px-4 py-3 flex gap-2.5 shadow-[0_-1px_6px_rgba(0,0,0,0.08)]`}>
        <input
          value={draft}
          onChange={(e) => handleDraftChange(e.target.value)}
          onKeyDown={(e) =>
            e.key === "Enter" && !e.shiftKey && (e.preventDefault(), sendMessage())
          }
          placeholder="Type a message…"
          className={`flex-1 px-4 py-2.5 rounded-full border border-gray-300 text-sm outline-none ${isDark ? "bg-[#1a1a2e] text-[#e0e0e0]" : "bg-[#f0f4f8] text-[#1a1a2e]"}`}
        />
        <button
          onClick={sendMessage}
