          className={`flex items-center gap-1.5 bg-[#4f8ef7] text-white border-none rounded-full px-5 py-2.5 text-sm transition-opacity ${draft.trim() ? "cursor-pointer opacity-100" : "cursor-not-allowed opacity-50"}`}
        >
          <Send size={14} />
          Send
        </button>
      </div>
    </div>
  );
}

