          const timer = setTimeout(() => {
            setTypingUsers((p) => {
              const n = new Map(p);
              n.delete(evt.user_id);
              return n;
            });
          }, TYPING_TIMEOUT);
          next.set(evt.user_id, timer);
          return next;
        });
      })
      .subscribe();

    channelRef.current = channel;

    return () => {
      supabase.removeChannel(channel);
    };
