// Mock useChatSocket hook
const useChatSocket = (user: User | null) => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [typingUsers, setTypingUsers] = useState<User[]>([]);
  const socketRef = useRef<WebSocket | null>(null);
  const messageQueueRef = useRef<Message[]>([]); // To store messages received before history is loaded

  const handleNewMessage = useCallback((msg: Message) => {
    setMessages(prev => [...prev, msg]);
  }, []);

  useEffect(() => {
    if (!user) {
      setMessages([]); // Clear messages if user logs out
      return;
    }

    // Mock WebSocket connection
    const ws = new WebSocket('ws://mock-chat-server'); // Dummy URL
    socketRef.current = ws;

    ws.onopen = () => {
      console.log('Mock WebSocket connected');
      // Simulate fetching history
      setTimeout(() => {
        const history: Message[] = [
          { id: '1', userId: 'system', userName: 'System', userAvatar: '', text: 'Welcome to the chat!', timestamp: new Date().toISOString() },
          { id: '2', userId: 'user_123', userName: 'Alice', userAvatar: 'https://i.pravatar.cc/32?u=alice', text: 'Hello everyone!', timestamp: new Date(Date.now() - 60000).toISOString() },
          { id: '3', userId: 'user_456', userName: 'Bob', userAvatar: 'https://i.pravatar.cc/32?u=bob', text: 'Hi Alice!', timestamp: new Date(Date.now() - 30000).toISOString() },
        ];
        setMessages(history);
        // Process any messages that arrived while history was loading
        setMessages(prev => [...prev, ...messageQueueRef.current]);
        messageQueueRef.current = []; // Clear the queue
      }, 1000);
    };

    ws.onmessage = (event) => {
      const data = JSON.parse(event.data as string);
      if (data.type === 'message') {
        // If history is not yet loaded (or still empty), queue the message
        if (messages.length === 0) {
          messageQueueRef.current.push(data.payload);
        } else {
          handleNewMessage(data.payload);
        }
      } else if (data.type === 'typing') {
        setTypingUsers(prev => {
          if (data.payload.isTyping && data.payload.user.id !== user.id && !prev.some(u => u.id === data.payload.user.id)) {
            return [...prev, data.payload.user];
          } else if (!data.payload.isTyping) {
            return prev.filter(u => u.id !== data.payload.user.id);
          }
          return prev;
        });
      }
    };

    ws.onclose = () => console.log('Mock WebSocket disconnected');
    ws.onerror = (error) => console.error('Mock WebSocket error:', error);

    return () => {
      ws.close();
    };
  }, [user, handleNewMessage, messages.length]); // Added messages.length to dependency array for queueing logic

  const sendMessage = useCallback((text: string) => {
    if (socketRef.current?.readyState === WebSocket.OPEN && user) {
      const message: Message = {
        id: 'msg_' + Date.now(),
        userId: user.id,
        userName: user.name,
        userAvatar: user.avatar,
        text,
        timestamp: new Date().toISOString(),
      };
      socketRef.current.send(JSON.stringify({ type: 'message', payload: message }));
      // Optimistic update
      handleNewMessage(message);
    }
  }, [user, handleNewMessage]);

  const sendTypingStatus = useCallback((isTyping: boolean) => {
    if (socketRef.current?.readyState === WebSocket.OPEN && user) {
      socketRef.current.send(JSON.stringify({ type: 'typing', payload: { user, isTyping } }));
    }
  }, [user]);

  return { messages, typingUsers, sendMessage, sendTypingStatus };
};


