              </View>

              <ScrollView horizontal showsHorizontalScrollIndicator={false} className="mb-4">
                {dates.map((dateValue) => {
                  const date = new Date(`${dateValue}T12:00:00`);
                  const selected = selectedDate === dateValue;

                  return (
                    <Pressable
                      key={dateValue}
                      onPress={() => setSelectedDate(dateValue)}
                      className={`mr-2.5 w-[62px] items-center rounded-2xl py-2.5 ${
                        selected ? "bg-blue-600" : "bg-white"
                      }`}
                    >
                      <Text className={`text-xs font-bold ${selected ? "text-white" : "text-slate-500"}`}>
                        {date.toLocaleDateString(undefined, { weekday: "short" })}
                      </Text>
                      <Text className={`mt-0.5 text-xl font-extrabold ${selected ? "text-white" : "text-gray-900"}`}>
                        {date.getDate()}
                      </Text>
                    </Pressable>
                  );
                })}
              </ScrollView>

              <View className="mb-2.5 flex-row items-center justify-between">
                <Text className="text-xl font-extrabold text-gray-900">Browse Events</Text>
                <Pressable
                  className="flex-row items-center rounded-xl bg-blue-600 px-3 py-2"
                  onPress={() => setModalOpen(true)}
