                  <Plus size={18} color="#fff" />
                  <Text className="ml-1 font-extrabold text-white">Create</Text>
                </Pressable>
              </View>

              {notifications[0] ? (
                <Text className="mb-3 rounded-xl bg-sky-100 p-2.5 text-sky-800">Latest: {notifications[0]}</Text>
              ) : null}
            </View>
