            </Text>
          }
        />

        <Modal visible={modalOpen} animationType="slide" presentationStyle="pageSheet">
          <KeyboardAvoidingView
            className="flex-1 bg-slate-50"
            behavior={Platform.OS === "ios" ? "padding" : undefined}
          >
            <SafeAreaView className="flex-1 bg-slate-50">
              <View className="flex-1 bg-slate-50 px-[18px] py-[18px]">
                <View className="mb-[18px] flex-row items-center justify-between">
                  <Text className="text-[26px] font-extrabold text-gray-900">Create Event</Text>
                  <Pressable onPress={() => setModalOpen(false)}>
                    <X size={26} color="#111827" />
                  </Pressable>
                </View>

                {draftFields.map((field) => (
                  <TextInput
                    key={field}
                    placeholder={draftLabels[field]}
                    value={draft[field]}
                    onChangeText={(value) => setDraft((currentDraft) => ({ ...currentDraft, [field]: value }))}
                    multiline={field === "description"}
                    className={`mb-3 rounded-[14px] bg-white p-3.5 text-base ${
                      field === "description" ? "min-h-24 align-top" : ""
                    }`}
                  />
                ))}

                <Pressable className="mt-1.5 items-center rounded-2xl bg-blue-600 p-4" onPress={createEvent}>
                  <Text className="text-base font-extrabold text-white">Publish Event</Text>
                </Pressable>
              </View>
            </SafeAreaView>
          </KeyboardAvoidingView>
        </Modal>
      </SafeAreaView>
    </KeyboardAvoidingView>
  );
}

