          </Text>
          <Text className="font-bold text-indigo-600">View profile</Text>
        </View>

        <ScrollView horizontal showsHorizontalScrollIndicator={false} className="mt-[10px] grow-0">
          {item.attendees.map((a) => (
            <View key={a.id} className="mr-2 h-[34px] w-[34px] items-center justify-center rounded-full bg-blue-100">
              <Text className="text-xs font-bold text-blue-700">
                {a.name
