                  .map((n) => n[0])
                  .join('')}
              </Text>
            </View>
          ))}
          <Text className="self-center text-gray-500">{item.attendees.length} attending</Text>
        </ScrollView>

        <View className="mt-3 flex-row items-center justify-between">
