          renderItem={renderEvent}
          contentContainerClassName={`px-4 pt-4 ${bottomListPaddingClass}`}
          ListHeaderComponent={
            <View>
              <View className="flex-row items-center justify-between">
                <View>
                  <Text className="text-[28px] font-bold text-gray-900">Discover Events</Text>
                  <Text className="mt-1 text-gray-500">Plan, browse, RSVP, and stay in sync.</Text>
                </View>
                <Pressable
                  onPress={() => Alert.alert('Notifications', `You have ${stats.notifications} new updates.`)}
                  className="flex-row items-center rounded-xl bg-indigo-50 px-3 py-2"
                >
                  <Bell size={16} color="#4338CA" />
                  <Text className="ml-2 font-bold text-indigo-700">{stats.notifications}</Text>
                </Pressable>
              </View>

              <View className="mb-[14px] mt-4 flex-row">
                <TextInput
                  value={query}
                  onChangeText={setQuery}
                  placeholder="Search events, hosts, locations"
                  placeholderTextColor="#8A8F98"
                  className="flex-1 rounded-[14px] border border-gray-200 bg-white px-[14px] py-3 text-gray-900"
                />
                <Pressable onPress={() => setShowCreate(true)} className="ml-[10px] flex-row items-center justify-center rounded-[14px] bg-gray-900 px-[14px]">
                  <Plus size={16} color="#FFFFFF" />
                  <Text className="ml-1 font-bold text-white">Create</Text>
                </Pressable>
              </View>

              <View className="mb-[14px] flex-row">
                <View className="mr-[10px] flex-1 rounded-2xl border border-gray-200 bg-white p-[14px]">
                  <Text className="text-xl font-extrabold text-gray-900">{stats.going}</Text>
                  <Text className="mt-0.5 text-gray-500">Going</Text>
