                <View className="mr-[10px] flex-1 rounded-2xl border border-gray-200 bg-white p-[14px]">
                  <Text className="text-xl font-extrabold text-gray-900">{stats.invites}</Text>
                  <Text className="mt-0.5 text-gray-500">Invites</Text>
