                <View className="flex-1 rounded-2xl border border-gray-200 bg-white p-[14px]">
                  <Text className="text-xl font-extrabold text-gray-900">{events.length}</Text>
                  <Text className="mt-0.5 text-gray-500">Events</Text>
                </View>
              </View>

              <ScrollView horizontal showsHorizontalScrollIndicator={false} className="mb-3 grow-0">
                <Chip label="All Dates" active={selectedDay === 'All'} onPress={() => setSelectedDay('All')} />
                {days.map((d) => (
                  <Chip key={d} label={d} active={selectedDay === d} onPress={() => setSelectedDay(d)} />
                ))}
              </ScrollView>

              <ScrollView horizontal showsHorizontalScrollIndicator={false} className="mb-4 grow-0">
                {categories.map((c) => (
                  <Chip key={c} label={c} active={category === c} onPress={() => setCategory(c)} />
                ))}
              </ScrollView>

              <Text className="mb-[10px] text-lg font-bold text-gray-900">Upcoming</Text>
            </View>
          }
          ListEmptyComponent={<Text className="mt-[30px] text-center text-gray-500">No events match your filters.</Text>}
        />

        <Modal visible={showCreate} animationType="slide" transparent>
          <View className="flex-1 justify-end bg-[rgba(17,24,39,0.35)]">
            <KeyboardAvoidingView behavior={Platform.OS === 'ios' ? 'padding' : undefined}>
              <View className={`rounded-t-[22px] bg-white p-4 ${bottomModalPaddingClass}`}>
                <View className="flex-row items-center justify-between">
                  <Text className="text-xl font-extrabold text-gray-900">Create Event</Text>
                  <Pressable onPress={() => setShowCreate(false)}>
                    <Text className="font-bold text-indigo-600">Close</Text>
