  const [events, setEvents] = useState(MOCK_EVENTS);
  const [search, setSearch] = useState('');
  const [activeCategory, setActiveCategory] = useState('All');
  const [selectedEvent, setSelectedEvent] = useState<Event | null>(null);
  const [createVisible, setCreateVisible] = useState(false);
  const [newTitle, setNewTitle] = useState('');
  const [newLocation, setNewLocation] = useState('');
  const [newDate, setNewDate] = useState('');
  const [newCategory, setNewCategory] = useState('Music');

  const filtered = events.filter(e => {
    const matchCat = activeCategory === 'All' || e.category === activeCategory;
    const matchSearch = e.title.toLowerCase().includes(search.toLowerCase()) || e.location.toLowerCase().includes(search.toLowerCase());
    return matchCat && matchSearch;
  });

  const toggleRSVP = useCallback((id: string) => {
    setEvents(prev => prev.map(e => e.id === id ? { ...e, rsvp: !e.rsvp } : e));
    Alert.alert('RSVP Updated', 'Your RSVP status has been saved.');
  }, []);

  const createEvent = () => {
    if (!newTitle || !newLocation || !newDate) { Alert.alert('Missing Fields', 'Please fill in all fields.'); return; }
    const ev: Event = { id: Date.now().toString(), title: newTitle, category: newCategory, date: newDate, location: newLocation, attendees: ['You'], rsvp: true, image: `https://picsum.photos/seed/${Date.now()}/300/150` };
    setEvents(prev => [ev, ...prev]);
    setCreateVisible(false);
    setNewTitle(''); setNewLocation(''); setNewDate(''); setNewCategory('Music');
    Alert.alert('Event Created', `"${ev.title}" has been added.`);
  };

  const renderEvent = ({ item }: { item: Event }) => (
    <TouchableOpacity
      style={{ backgroundColor: '#fff', borderRadius: 16, marginBottom: 14, overflow: 'hidden', shadowColor: '#000', shadowOpacity: 0.08, shadowRadius: 6, elevation: 3 }}
      onPress={() => setSelectedEvent(item)}
      activeOpacity={0.85}
    >
      <Image source={{ uri: item.image }} style={{ width: '100%', height: 130 }} />
      <View style={{ padding: 12 }}>
        <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: 4 }}>
          <Text style={{ fontSize: 17, fontWeight: '700', color: '#1A1A2E', flex: 1 }}>{item.title}</Text>
          <View style={{ borderRadius: 12, paddingHorizontal: 10, paddingVertical: 3, marginLeft: 8, backgroundColor: item.rsvp ? '#4CAF50' : '#9E9E9E' }}>
            <Text style={{ color: '#fff', fontSize: 12, fontWeight: '600' }}>{item.rsvp ? 'Going' : 'RSVP'}</Text>
          </View>
        </View>
        <View style={{ flexDirection: 'row', alignItems: 'center', marginTop: 2 }}>
          <Calendar size={13} color="#666" />
          <Text style={{ fontSize: 13, color: '#666', marginLeft: 4, marginRight: 10 }}>{item.date}</Text>
          <MapPin size={13} color="#666" />
          <Text style={{ fontSize: 13, color: '#666', marginLeft: 4 }}>{item.location}</Text>
        </View>
        <View style={{ flexDirection: 'row', alignItems: 'center', marginTop: 2 }}>
          <Users size={13} color="#666" />
          <Text style={{ fontSize: 13, color: '#666', marginLeft: 4 }}>{item.attendees.length} attendees · {item.category}</Text>
        </View>
      </View>
    </TouchableOpacity>
  );

  type FieldTuple = [string, string, (v: string) => void];

  const formFields: FieldTuple[] = [
    ['Title', newTitle, setNewTitle],
    ['Location', newLocation, setNewLocation],
    ['Date (YYYY-MM-DD)', newDate, setNewDate],
  ];

  return (
    <KeyboardAvoidingView
      style={{ flex: 1, backgroundColor: '#F5F6FA' }}
      behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
    >
      <View style={{ flex: 1, paddingTop: insets.top }}>
        <View style={{ flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', paddingHorizontal: 16, paddingVertical: 12 }}>
          <Text style={{ fontSize: 28, fontWeight: '700', color: '#1A1A2E' }}>Events</Text>
          <TouchableOpacity
            style={{ backgroundColor: '#3F51B5', borderRadius: 20, paddingHorizontal: 16, paddingVertical: 8, flexDirection: 'row', alignItems: 'center' }}
            onPress={() => setCreateVisible(true)}
          >
            <Plus size={14} color="#fff" />
            <Text style={{ color: '#fff', fontWeight: '600', fontSize: 14, marginLeft: 4 }}>New</Text>
          </TouchableOpacity>
        </View>

        <TextInput
          style={{ marginHorizontal: 16, marginBottom: 8, backgroundColor: '#fff', borderRadius: 12, paddingHorizontal: 14, paddingVertical: 10, fontSize: 15, color: '#333', shadowColor: '#000', shadowOpacity: 0.06, shadowRadius: 4, elevation: 2 }}
          placeholder="Search events or locations…"
          value={search}
          onChangeText={setSearch}
          placeholderTextColor="#999"
        />

        <ScrollView
          horizontal
          showsHorizontalScrollIndicator={false}
          style={{ flexGrow: 0, maxHeight: 48, marginBottom: 4 }}
          contentContainerStyle={{ paddingHorizontal: 16 }}
        >
          {CATEGORIES.map(cat => (
            <TouchableOpacity
              key={cat}
              style={{ borderRadius: 20, borderWidth: 1.5, borderColor: activeCategory === cat ? '#3F51B5' : '#C5CAE9', paddingHorizontal: 14, paddingVertical: 6, marginRight: 8, backgroundColor: activeCategory === cat ? '#3F51B5' : '#fff' }}
              onPress={() => setActiveCategory(cat)}
            >
              <Text style={{ color: activeCategory === cat ? '#fff' : '#5C6BC0', fontWeight: '600', fontSize: 13 }}>{cat}</Text>
            </TouchableOpacity>
          ))}
        </ScrollView>

        <FlatList
          data={filtered}
          keyExtractor={i => i.id}
          renderItem={renderEvent}
          contentContainerStyle={{ padding: 16, paddingTop: 8 }}
          ListEmptyComponent={<Text style={{ textAlign: 'center', color: '#aaa', marginTop: 40, fontSize: 16 }}>No events found.</Text>}
        />
      </View>

      <Modal visible={!!selectedEvent} animationType="slide" presentationStyle="pageSheet" onRequestClose={() => setSelectedEvent(null)}>
        {selectedEvent && (
          <View style={{ flex: 1, backgroundColor: '#fff', paddingTop: insets.top }}>
            <Image source={{ uri: selectedEvent.image }} style={{ width: '100%', height: 200 }} />
            <ScrollView contentContainerStyle={{ padding: 20 }}>
              <Text style={{ fontSize: 24, fontWeight: '700', color: '#1A1A2E', marginBottom: 10 }}>{selectedEvent.title}</Text>
              <View style={{ flexDirection: 'row', alignItems: 'center', marginBottom: 6 }}>
                <Calendar size={15} color="#555" />
                <Text style={{ fontSize: 15, color: '#555', marginLeft: 6 }}>{selectedEvent.date}</Text>
              </View>
              <View style={{ flexDirection: 'row', alignItems: 'center', marginBottom: 6 }}>
                <MapPin size={15} color="#555" />
                <Text style={{ fontSize: 15, color: '#555', marginLeft: 6 }}>{selectedEvent.location}</Text>
              </View>
              <View style={{ flexDirection: 'row', alignItems: 'center', marginBottom: 6 }}>
                <Tag size={15} color="#555" />
                <Text style={{ fontSize: 15, color: '#555', marginLeft: 6 }}>{selectedEvent.category}</Text>
              </View>
              <Text style={{ fontSize: 16, fontWeight: '700', color: '#1A1A2E', marginTop: 16, marginBottom: 8 }}>Attendees</Text>
              <View style={{ flexDirection: 'row', flexWrap: 'wrap', marginBottom: 6 }}>
                {selectedEvent.attendees.map(a => (
                  <View key={a} style={{ width: 36, height: 36, borderRadius: 18, backgroundColor: '#3F51B5', justifyContent: 'center', alignItems: 'center', marginRight: 6, marginBottom: 6 }}>
                    <Text style={{ color: '#fff', fontWeight: '700', fontSize: 14 }}>{a[0]}</Text>
                  </View>
                ))}
              </View>
              <Text style={{ fontSize: 13, color: '#777', marginBottom: 20 }}>{selectedEvent.attendees.join(', ')}</Text>
              <TouchableOpacity
                style={{ borderRadius: 14, paddingVertical: 14, alignItems: 'center', marginBottom: 10, backgroundColor: selectedEvent.rsvp ? '#F44336' : '#4CAF50' }}
                onPress={() => {
                  toggleRSVP(selectedEvent.id);
                  setSelectedEvent(prev => prev ? { ...prev, rsvp: !prev.rsvp } : null);
                }}
              >
                <Text style={{ color: '#fff', fontSize: 16, fontWeight: '700' }}>{selectedEvent.rsvp ? 'Cancel RSVP' : 'RSVP Now'}</Text>
              </TouchableOpacity>
              <TouchableOpacity
                style={{ borderRadius: 14, paddingVertical: 12, alignItems: 'center', backgroundColor: '#ECEFF1' }}
                onPress={() => setSelectedEvent(null)}
              >
                <Text style={{ color: '#555', fontSize: 15, fontWeight: '600' }}>Close</Text>
              </TouchableOpacity>
            </ScrollView>
          </View>
        )}
      </Modal>

      <Modal visible={createVisible} animationType="slide" presentationStyle="pageSheet" onRequestClose={() => setCreateVisible(false)}>
        <KeyboardAvoidingView
          style={{ flex: 1, backgroundColor: '#fff' }}
          behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
        >
          <View style={{ flex: 1, paddingTop: insets.top }}>
            <Text style={{ fontSize: 24, fontWeight: '700', color: '#1A1A2E', marginBottom: 10, paddingHorizontal: 20, paddingTop: 10 }}>Create Event</Text>
            <ScrollView contentContainerStyle={{ padding: 20 }}>
              {formFields.map(([label, val, setter]) => (
                <View key={label} style={{ marginBottom: 14 }}>
                  <Text style={{ fontSize: 14, fontWeight: '600', color: '#444', marginBottom: 6 }}>{label}</Text>
                  <TextInput
                    style={{ backgroundColor: '#F5F6FA', borderRadius: 10, paddingHorizontal: 14, paddingVertical: 10, fontSize: 15, color: '#333', borderWidth: 1, borderColor: '#E0E0E0' }}
                    value={val}
                    onChangeText={setter}
                    placeholder={label}
                    placeholderTextColor="#aaa"
                  />
                </View>
              ))}
              <Text style={{ fontSize: 14, fontWeight: '600', color: '#444', marginBottom: 6 }}>Category</Text>
              <ScrollView
                horizontal
                showsHorizontalScrollIndicator={false}
                style={{ flexGrow: 0, marginBottom: 16 }}
              >
                {CATEGORIES.filter(c => c !== 'All').map(cat => (
                  <TouchableOpacity
                    key={cat}
                    style={{ borderRadius: 20, borderWidth: 1.5, borderColor: newCategory === cat ? '#3F51B5' : '#C5CAE9', paddingHorizontal: 14, paddingVertical: 6, marginRight: 8, backgroundColor: newCategory === cat ? '#3F51B5' : '#fff' }}
                    onPress={() => setNewCategory(cat)}
                  >
                    <Text style={{ color: newCategory === cat ? '#fff' : '#5C6BC0', fontWeight: '600', fontSize: 13 }}>{cat}</Text>
                  </TouchableOpacity>
                ))}
              </ScrollView>
              <TouchableOpacity
                style={{ borderRadius: 14, paddingVertical: 14, alignItems: 'center', marginBottom: 10, backgroundColor: '#3F51B5', flexDirection: 'row', justifyContent: 'center' }}
                onPress={createEvent}
              >
                <Check size={16} color="#fff" />
                <Text style={{ color: '#fff', fontSize: 16, fontWeight: '700', marginLeft: 6 }}>Create Event</Text>
              </TouchableOpacity>
              <TouchableOpacity
                style={{ borderRadius: 14, paddingVertical: 12, alignItems: 'center', backgroundColor: '#ECEFF1', flexDirection: 'row', justifyContent: 'center' }}
                onPress={() => setCreateVisible(false)}
              >
                <X size={15} color="#555" />
                <Text style={{ color: '#555', fontSize: 15, fontWeight: '600', marginLeft: 6 }}>Cancel</Text>
              </TouchableOpacity>
            </ScrollView>
          </View>
        </KeyboardAvoidingView>
      </Modal>
    </KeyboardAvoidingView>
  );
}

