const CATEGORIES = ['All', 'Music', 'Tech', 'Sports', 'Food', 'Art', 'Networking'];

const MOCK_EVENTS = [
  { id: '1', title: 'React Native Meetup', date: '2024-03-15', time: '6:00 PM', category: 'Tech', location: 'Downtown Hub, SF', attendees: 42, rsvp: false, image: 'https://picsum.photos/400/200?random=1' },
  { id: '2', title: 'Jazz Night', date: '2024-03-18', time: '8:00 PM', category: 'Music', location: 'Blue Note Lounge', attendees: 85, rsvp: true, image: 'https://picsum.photos/400/200?random=2' },
  { id: '3', title: 'Food Truck Festival', date: '2024-03-20', time: '11:00 AM', category: 'Food', location: 'Central Park', attendees: 200, rsvp: false, image: 'https://picsum.photos/400/200?random=3' },
  { id: '4', title: 'Basketball Tournament', date: '2024-03-22', time: '2:00 PM', category: 'Sports', location: 'City Arena', attendees: 120, rsvp: false, image: 'https://picsum.photos/400/200?random=4' },
  { id: '5', title: 'Art Gallery Opening', date: '2024-03-25', time: '7:00 PM', category: 'Art', location: 'Modern Art Museum', attendees: 60, rsvp: true, image: 'https://picsum.photos/400/200?random=5' },
];

export default function HomeScreen() {
  const navigation = useNavigation<any>();
  const insets = useSafeAreaInsets();
  const [search, setSearch] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('All');
  const [showCalendar, setShowCalendar] = useState(false);
  const [selectedDate, setSelectedDate] = useState('');
  const [events, setEvents] = useState(MOCK_EVENTS);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [newEvent, setNewEvent] = useState({ title: '', date: '', time: '', category: 'Tech', location: '' });
  const [notifCount] = useState(3);

  const filtered = useMemo(() => {
    return events.filter(e => {
      const matchCat = selectedCategory === 'All' || e.category === selectedCategory;
      const matchSearch = e.title.toLowerCase().includes(search.toLowerCase()) || e.location.toLowerCase().includes(search.toLowerCase());
      const matchDate = !selectedDate || e.date === selectedDate;
      return matchCat && matchSearch && matchDate;
    });
  }, [events, selectedCategory, search, selectedDate]);

  const toggleRSVP = useCallback((id: string) => {
    setEvents(prev => prev.map(e => e.id === id ? { ...e, rsvp: !e.rsvp, attendees: e.rsvp ? e.attendees - 1 : e.attendees + 1 } : e));
  }, []);

  const handleCreate = () => {
    if (!newEvent.title || !newEvent.date) {
      Alert.alert('Error', 'Title and date are required');
    } else {
      const created = { ...newEvent, id: Date.now().toString(), attendees: 0, rsvp: false, image: `https://picsum.photos/400/200?random=${encodeURIComponent(Date.now().toString())}` };
      setEvents(prev => [created, ...prev]);
      setNewEvent({ title: '', date: '', time: '', category: 'Tech', location: '' });
      setShowCreateModal(false);
    }
  };

  const markedDates = useMemo(() => {
    const marks: any = {};
    events.forEach(e => { marks[e.date] = { marked: true, dotColor: '#6C63FF' }; });
    if (selectedDate) {
      marks[selectedDate] = { ...marks[selectedDate], selected: true, selectedColor: '#6C63FF' };
    }
    return marks;
  }, [events, selectedDate]);

  const renderEvent = ({ item }: { item: typeof MOCK_EVENTS[0] }) => (
    <TouchableOpacity className="bg-white rounded-2xl mb-4 overflow-hidden shadow-sm" activeOpacity={0.85}>
      <Image source={{ uri: item.image }} className="w-full h-36" />
