            <Text className={`text-xs ${item.rsvp ? 'text-white' : 'text-gray-500'}`}>{item.rsvp ? 'Going' : item.category}</Text>
          </View>
        </View>
        <View className="flex-row items-center gap-1.5 mb-1">
          <Clock size={14} color="#888" />
          <Text className="text-sm text-gray-400">{item.date} · {item.time}</Text>
        </View>
        <View className="flex-row items-center gap-1.5 mb-1">
          <MapPin size={14} color="#888" />
          <Text className="text-sm text-gray-400">{item.location}</Text>
        </View>
        <View className="flex-row justify-between items-center mt-2">
          <View className="flex-row items-center gap-1.5">
            <Users size={14} color="#888" />
            <Text className="text-sm text-gray-400">{item.attendees} attending</Text>
          </View>
          <TouchableOpacity className={`px-5 py-2 rounded-2xl border-2 border-violet-500 ${item.rsvp ? 'bg-violet-500' : ''}`} onPress={() => toggleRSVP(item.id)}>
            <Text className={`font-semibold text-sm ${item.rsvp ? 'text-white' : 'text-violet-500'}`}>{item.rsvp ? 'Cancel' : 'RSVP'}</Text>
          </TouchableOpacity>
        </View>
      </View>
    </TouchableOpacity>
  );

  return (
    <View className={`flex-1 bg-gray-50 pt-[${insets.top}px]`}>
      <View className="flex-row items-center justify-between px-4 py-3">
