            <Bell size={22} color="#333" />
            {notifCount > 0 ? (
              <View className="absolute top-0.5 right-0.5 bg-red-500 rounded-full w-4 h-4 items-center justify-center">
                <Text className="text-white text-[9px]">{notifCount}</Text>
              </View>
            ) : (
              <></>
            )}
          </TouchableOpacity>
        </View>
      </View>
      <KeyboardAvoidingView behavior={Platform.OS === 'ios' ? 'padding' : 'height'} className="flex-1">
        <View className="flex-row items-center bg-white mx-4 rounded-xl px-3 h-11 mb-2">
          <Search size={18} color="#999" />
          <TextInput className="flex-1 ml-2 text-base text-gray-800" placeholder="Search events or locations..." value={search} onChangeText={setSearch} placeholderTextColor="#999" />
          {(search || selectedDate) ? (
            <TouchableOpacity onPress={() => { setSearch(''); setSelectedDate(''); }}>
              <X size={18} color="#999" />
