        <FlatList data={filtered} renderItem={renderEvent} keyExtractor={i => i.id} contentContainerClassName="p-4 pb-20" ListEmptyComponent={<Text className="text-center text-gray-400 mt-10 text-base">No events found</Text>} showsVerticalScrollIndicator={false} />
