  TextInput,
  Modal,
  ScrollView,
  Alert,
  KeyboardAvoidingView,
  Platform,
} from 'react-native';
import { Calendar, MapPin, Bell, User, Plus, List } from 'lucide-react-native'; // Prefer lucide-react-native for icons
import { useSafeAreaInsets } from 'react-native-safe-area-context'; // Use useSafeAreaInsets hook
import { styled } from 'nativewind'; // Import styled from nativewind

// --- Mock Data and Interfaces ---
interface User {
  id: string;
  name: string;
}

interface Event {
  id: string;
  title: string;
  date: string; // e.g., "2023-10-27 19:00"
  location: string;
  category: string;
  description: string;
  attendees: User[];
  rsvped: boolean; // Client-side state for current user
}

const MOCK_USERS: User[] = [
  { id: 'u1', name: 'Alice' },
  { id: 'u2', name: 'Bob' },
  { id: 'u3', name: 'Charlie' },
];

const MOCK_EVENTS: Event[] = [
  {
    id: 'e1',
    title: 'Tech Meetup',
    date: '2023-11-15 18:30',
    location: 'Innovation Hub',
    category: 'Tech',
    description: 'A monthly gathering for tech enthusiasts.',
    attendees: [MOCK_USERS[0], MOCK_USERS[1]],
    rsvped: false,
  },
  {
    id: 'e2',
    title: 'Community Garden Day',
    date: '2023-11-18 10:00',
    location: 'Central Park Garden',
    category: 'Community',
    description: 'Help us maintain our beautiful community garden.',
    attendees: [MOCK_USERS[2]],
    rsvped: true,
  },
  {
    id: 'e3',
    title: 'Art Exhibition Opening',
    date: '2023-11-20 19:00',
    location: 'City Art Gallery',
    category: 'Art',
    description: 'Discover new local artists.',
    attendees: [],
    rsvped: false,
  },
  {
    id: 'e4',
    title: 'React Native Workshop',
    date: '2023-12-02 09:00',
    location: 'Online (Zoom)',
    category: 'Tech',
    description: 'Learn the basics of React Native development.',
    attendees: [MOCK_USERS[0]],
    rsvped: false,
  },
];

const CATEGORIES = ['All', 'Tech', 'Community', 'Art', 'Music', 'Sports'];

// --- Styled Components with NativeWind ---
const StyledView = styled(View);
const StyledText = styled(Text);
const StyledTouchableOpacity = styled(TouchableOpacity);
const StyledTextInput = styled(TextInput);
const StyledScrollView = styled(ScrollView);

// --- HomeScreen Component ---
const HomeScreen: React.FC = () => {
  const insets = useSafeAreaInsets(); // Use useSafeAreaInsets hook
  const [events, setEvents] = useState<Event[]>(MOCK_EVENTS);
  const [filteredEvents, setFilteredEvents] = useState<Event[]>(MOCK_EVENTS);
  const [searchQuery, setSearchQuery] = useState<string>('');
  const [selectedCategory, setSelectedCategory] = useState<string>('All');
  const [isCreateModalVisible, setIsCreateModalVisible] = useState<boolean>(false);
  const [isCalendarView, setIsCalendarView] = useState<boolean>(false); // Simple toggle for calendar view

  // New Event Form State
  const [newEventTitle, setNewEventTitle] = useState<string>('');
  const [newEventDate, setNewEventDate] = useState<string>('');
  const [newEventLocation, setNewEventLocation] = useState<string>('');
  const [newEventCategory, setNewEventCategory] = useState<string>('Tech');

  useEffect(() => {
    let currentEvents = [...events];

    // Apply category filter
    if (selectedCategory !== 'All') {
      currentEvents = currentEvents.filter(event => event.category === selectedCategory);
    } else {
      console.log('No category filter applied, showing all events.');
    }

    // Apply search filter
    if (searchQuery) {
      currentEvents = currentEvents.filter(
        event =>
          event.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
          event.description.toLowerCase().includes(searchQuery.toLowerCase()) ||
          event.location.toLowerCase().includes(searchQuery.toLowerCase())
      );
    } else {
      console.log('No search query applied, showing events based on category.');
    }

    setFilteredEvents(currentEvents);
  }, [events, searchQuery, selectedCategory]);

  const toggleRSVP = (eventId: string) => {
    setEvents(prevEvents =>
      prevEvents.map(event =>
        event.id === eventId ? { ...event, rsvped: !event.rsvped } : event
      )
    );
  };

  const handleCreateEvent = () => {
    if (!newEventTitle || !newEventDate || !newEventLocation || !newEventCategory) {
      Alert.alert('Error', 'Please fill all fields.');
      return;
    }

    const newEvent: Event = {
      id: `e${events.length + 1}`, // Simple ID generation
      title: newEventTitle,
      date: newEventDate,
      location: newEventLocation,
      category: newEventCategory,
      description: 'User-created event.', // Default description
      attendees: [],
      rsvped: true, // User who created it automatically RSVPs
    };

    setEvents(prevEvents => [...prevEvents, newEvent]);
    setIsCreateModalVisible(false);
    // Clear form
    setNewEventTitle('');
    setNewEventDate('');
    setNewEventLocation('');
    setNewEventCategory('Tech');
  };

  const renderEventItem = ({ item }: { item: Event }) => (
    <StyledTouchableOpacity className="bg-white rounded-lg p-4 mb-4 shadow-md shadow-black/5 elevation-3" onPress={() => Alert.alert('Event Details', `View details for ${item.title}`)}>
      <StyledText className="text-lg font-bold mb-1">{item.title}</StyledText>
      <StyledText className="text-gray-600 text-sm mb-1 flex-row items-center"><Calendar size={14} color="#555" /> {item.date}</StyledText>
      <StyledText className="text-gray-600 text-sm mb-1 flex-row items-center"><MapPin size={14} color="#555" /> {item.location}</StyledText>
      <StyledText className="text-gray-500 text-xs mb-1">Category: {item.category}</StyledText>
      <StyledText className="text-gray-500 text-xs mb-2">Attendees: {item.attendees.length}</StyledText>
      <StyledTouchableOpacity
        className={`py-2 px-3 rounded-full self-start ${item.rsvped ? 'bg-gray-500' : 'bg-green-600'}`}
        onPress={() => toggleRSVP(item.id)}
      >
        <StyledText className="text-white font-bold text-xs">{item.rsvped ? 'RSVPed' : 'RSVP'}</StyledText>
      </StyledTouchableOpacity>
    </StyledTouchableOpacity>
  );

  return (
    <KeyboardAvoidingView
      className="flex-1"
      behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
      keyboardVerticalOffset={Platform.OS === 'ios' ? 0 : 20}
    >
      <StyledView className="flex-1 bg-gray-100" style={{ paddingTop: insets.top }}>
        {/* Header */}
        <StyledView className="flex-row items-center p-4 bg-white border-b border-gray-200">
          <StyledTextInput
            className="flex-1 h-10 bg-gray-100 rounded-full px-4 mr-2"
            placeholder="Search events..."
            value={searchQuery}
            onChangeText={setSearchQuery}
          />
          <StyledTouchableOpacity onPress={() => Alert.alert('Notifications', 'No new notifications.')}>
            <Bell size={24} color="black" className="ml-2" />
          </StyledTouchableOpacity>
          <StyledTouchableOpacity onPress={() => Alert.alert('Profile', 'View user profile.')}>
            <User size={24} color="black" className="ml-2" />
          </StyledTouchableOpacity>
        </StyledView>

        {/* Category Filters */}
        <StyledScrollView horizontal showsHorizontalScrollIndicator={false} className="py-2 px-2 bg-white border-b border-gray-200" contentContainerStyle={{ flexGrow: 0 }}>
          {CATEGORIES.map(category => (
            <StyledTouchableOpacity
              key={category}
              className={`py-2 px-4 rounded-full mx-1 ${
                selectedCategory === category ? 'bg-blue-600' : 'bg-gray-200'
              }`}
              onPress={() => setSelectedCategory(category)}
            >
              <StyledText
                className={`font-medium ${
                  selectedCategory === category ? 'text-white' : 'text-gray-700'
                }`}
              >
                {category}
              </StyledText>
            </StyledTouchableOpacity>
          ))}
        </StyledScrollView>

        {/* Calendar View Toggle */}
        <StyledTouchableOpacity className="flex-row items-center justify-center p-3 bg-gray-200 border-b border-gray-300" onPress={() => setIsCalendarView(!isCalendarView)}>
          {isCalendarView ? <List size={20} color="black" /> : <Calendar size={20} color="black" />}
          <StyledText className="ml-1.5 font-semibold">{isCalendarView ? 'List View' : 'Calendar View'}</StyledText>
        </StyledTouchableOpacity>

        {/* Main Content */}
        {isCalendarView ? (
          <StyledView className="flex-1 justify-center items-center bg-gray-50">
            <StyledText className="text-lg text-gray-500 text-center leading-7">
              <Calendar size={50} color="#ccc" />
              {'\n'}Calendar View Placeholder
              {'\n'} (Displays events on a calendar grid)
            </StyledText>
          </StyledView>
        ) : (
          <FlatList
            data={filteredEvents}
            renderItem={renderEventItem}
            keyExtractor={item => item.id}
            contentContainerStyle={{ padding: 16 }}
            ListEmptyComponent={
              <StyledText className="text-center mt-12 text-base text-gray-600">No events found for your criteria.</StyledText>
            }
          />
        )}

        {/* Create Event Button */}
        <StyledTouchableOpacity className="absolute bottom-8 right-8 bg-blue-600 w-16 h-16 rounded-full justify-center items-center shadow-lg shadow-black/25 elevation-5" onPress={() => setIsCreateModalVisible(true)}>
          <Plus size={30} color="white" />
        </StyledTouchableOpacity>

        {/* Create Event Modal */}
        <Modal
          animationType="slide"
          transparent={true}
          visible={isCreateModalVisible}
          onRequestClose={() => setIsCreateModalVisible(false)}
        >
          <StyledView className="flex-1 justify-center items-center bg-black/50">
            <StyledView className="m-5 bg-white rounded-2xl p-8 items-center shadow-lg shadow-black/25 elevation-5 w-[90%]">
              <StyledText className="text-xl font-bold mb-5">Create New Event</StyledText>
              <StyledTextInput
                className="w-full h-11 border border-gray-300 rounded-lg px-4 mb-4"
                placeholder="Event Title"
                value={newEventTitle}
                onChangeText={setNewEventTitle}
              />
              <StyledTextInput
                className="w-full h-11 border border-gray-300 rounded-lg px-4 mb-4"
                placeholder="Date (YYYY-MM-DD HH:MM)"
                value={newEventDate}
                onChangeText={setNewEventDate}
              />
              <StyledTextInput
                className="w-full h-11 border border-gray-300 rounded-lg px-4 mb-4"
                placeholder="Location"
                value={newEventLocation}
                onChangeText={setNewEventLocation}
              />
              <StyledView className="w-full mb-4">
                <StyledText>Category:</StyledText>
                <StyledScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{ flexGrow: 0 }}>
                  {CATEGORIES.filter(c => c !== 'All').map(cat => (
                    <StyledTouchableOpacity
                      key={cat}
                      className={`py-2 px-3 rounded-full mx-1 mt-2 ${
                        newEventCategory === cat ? 'bg-blue-600' : 'bg-gray-200'
                      }`}
                      onPress={() => setNewEventCategory(cat)}
                    >
                      <StyledText className={`${newEventCategory === cat ? 'text-white' : 'text-gray-700'}`}>{cat}</StyledText>
                    </StyledTouchableOpacity>
                  ))}
                </StyledScrollView>
              </StyledView>

              <StyledView className="flex-row justify-between w-full mt-5">
                <StyledTouchableOpacity className="rounded-xl py-2 px-4 elevation-2 flex-1 mx-1 bg-red-600" onPress={() => setIsCreateModalVisible(false)}>
                  <StyledText className="text-white font-bold text-center">Cancel</StyledText>
                </StyledTouchableOpacity>
                <StyledTouchableOpacity className="rounded-xl py-2 px-4 elevation-2 flex-1 mx-1 bg-blue-600" onPress={handleCreateEvent}>
                  <StyledText className="text-white font-bold text-center">Create Event</StyledText>
                </StyledTouchableOpacity>
              </StyledView>
            </StyledView>
          </StyledView>
        </Modal>
      </StyledView>
    </KeyboardAvoidingView>
  );
};

export default HomeScreen;

