async function withRetry<T>({ fn, attempts }: RetryOptions<T>): Promise<T> {
  let lastError: unknown;
  const maxAttempts = Math.max(1, attempts ?? 3);

  for (let attempt = 0; attempt < maxAttempts; attempt += 1) {
    try {
      return await fn();
