function isValidTransactionStatus(status: unknown): status is 'completed' | 'pending' {
  return status === 'completed' || status === 'pending';
}

async function checkIdempotency(idempotencyKey: string): Promise<TransferResult | null> {
  const existing = await db.transaction.findUnique({
    where: { idempotencyKey },
  });
