const ALL_REPORT_ROLES = new Set(["admin", "owner", "manager", "analyst", "underwriter"]);
const AGENT_ROLES = new Set(["agent", "producer"]);

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function readStringProperty({ source, key }: { source: unknown; key: string }) {
  if (!isRecord(source)) {
    return null;
  }

  const value = source[key];
  return typeof value === "string" ? value : null;
}

function normalizeSessionUser(user: unknown): SessionUser | null {
  const id = readStringProperty({ source: user, key: "id" });

  if (!id) {
