function parseFilters(searchParams: URLSearchParams): ReportFilters {
  return {
    startDate: searchParams.get('startDate'),
    endDate: searchParams.get('endDate'),
    agentId: searchParams.get('agentId'),
    productType: searchParams.get('productType'),
    status: searchParams.get('status'),
    region: searchParams.get('region'),
  };
}

function buildWhereClause(filters: ReportFilters) {
  const where: Record<string, unknown> = {};

  if (filters.startDate !== null || filters.endDate !== null) {
    const createdAt: Record<string, unknown> = {};
    if (filters.startDate !== null) {
      createdAt.gte = new Date(filters.startDate);
    } else {
      logger.debug('No startDate filter provided; skipping gte constraint');
    }
    if (filters.endDate !== null) {
      createdAt.lte = new Date(filters.endDate);
    } else {
      logger.debug('No endDate filter provided; skipping lte constraint');
    }
    where.createdAt = createdAt;
  } else {
    logger.debug('No date range filters provided');
  }

  if (filters.agentId !== null) {
    where.agentId = filters.agentId;
  } else {
    logger.debug('No agentId filter provided');
  }
  if (filters.productType !== null) {
    where.productType = filters.productType;
  } else {
    logger.debug('No productType filter provided');
  }
  if (filters.status !== null) {
    where.status = filters.status;
  } else {
    logger.debug('No status filter provided');
  }
  if (filters.region !== null) {
    where.region = filters.region;
  } else {
    logger.debug('No region filter provided');
  }

  return where;
}

function calcConversionRate(params: { quotes: number; bound: number }): number {
  if (params.quotes === 0) return 0;
  return Math.round((params.bound / params.quotes) * 10000) / 100;
}

function aggregateRecords(records: Array<Record<string, unknown>>): AggregatedReport {
  const byProduct: AggregatedReport['byProduct'] = {};
  const byAgent: AggregatedReport['byAgent'] = {};
  const byRegion: AggregatedReport['byRegion'] = {};

  let totalQuotes = 0;
  let totalBound = 0;
  let totalPremium = 0;
  let minDate = '';
  let maxDate = '';

  for (const r of records) {
    const isBound = r.status === 'bound';
    const rawPremium = typeof r.premium === 'number' ? r.premium : 0;
    const premium = isBound ? rawPremium : 0;
    const createdAt = r.createdAt instanceof Date ? r.createdAt : new Date(String(r.createdAt));
    const dateStr = createdAt.toISOString();

    if (!minDate || dateStr < minDate) {
      minDate = dateStr;
    } else {
      logger.debug('Current date is not earlier than minDate; skipping update');
    }
    if (!maxDate || dateStr > maxDate) {
      maxDate = dateStr;
    } else {
      logger.debug('Current date is not later than maxDate; skipping update');
    }

    totalQuotes++;
    if (isBound) {
      totalBound++;
      totalPremium += premium;
    } else {
      logger.debug('Record is not bound; skipping premium aggregation for this record');
    }

    const product = typeof r.productType === 'string' ? r.productType : 'unknown';
    if (!byProduct[product]) {
      byProduct[product] = { quotes: 0, bound: 0, premium: 0, conversionRate: 0 };
    } else {
      logger.debug(`Product bucket "${product}" already exists`);
    }
    byProduct[product].quotes++;
    if (isBound) {
      byProduct[product].bound++;
      byProduct[product].premium += premium;
    } else {
      logger.debug(`Record not bound for product "${product}"; skipping bound/premium increment`);
    }

    const agent = typeof r.agentId === 'string' ? r.agentId : 'unassigned';
    if (!byAgent[agent]) {
      byAgent[agent] = { quotes: 0, bound: 0, premium: 0, conversionRate: 0 };
    } else {
      logger.debug(`Agent bucket "${agent}" already exists`);
    }
    byAgent[agent].quotes++;
    if (isBound) {
      byAgent[agent].bound++;
      byAgent[agent].premium += premium;
    } else {
      logger.debug(`Record not bound for agent "${agent}"; skipping bound/premium increment`);
    }

    const region = typeof r.region === 'string' ? r.region : 'unknown';
    if (!byRegion[region]) {
      byRegion[region] = { quotes: 0, bound: 0, premium: 0, conversionRate: 0 };
    } else {
      logger.debug(`Region bucket "${region}" already exists`);
    }
    byRegion[region].quotes++;
    if (isBound) {
      byRegion[region].bound++;
      byRegion[region].premium += premium;
    } else {
      logger.debug(`Record not bound for region "${region}"; skipping bound/premium increment`);
    }
  }

  for (const key of Object.keys(byProduct)) {
    byProduct[key].conversionRate = calcConversionRate({ quotes: byProduct[key].quotes, bound: byProduct[key].bound });
  }
  for (const key of Object.keys(byAgent)) {
    byAgent[key].conversionRate = calcConversionRate({ quotes: byAgent[key].quotes, bound: byAgent[key].bound });
  }
  for (const key of Object.keys(byRegion)) {
    byRegion[key].conversionRate = calcConversionRate({ quotes: byRegion[key].quotes, bound: byRegion[key].bound });
  }

  return {
    totalQuotes,
    totalPoliciesBound: totalBound,
    totalPremium: Math.round(totalPremium * 100) / 100,
    averagePremium: totalBound > 0 ? Math.round((totalPremium / totalBound) * 100) / 100 : 0,
    conversionRate: calcConversionRate({ quotes: totalQuotes, bound: totalBound }),
    byProduct,
    byAgent,
    byRegion,
    periodStart: minDate,
    periodEnd: maxDate,
  };
}

function toCsv(report: AggregatedReport): string {
  const lines: string[] = [];
  lines.push('Category,Key,Quotes,Bound,Premium,ConversionRate');

  lines.push(`Summary,Overall,${report.totalQuotes},${report.totalPoliciesBound},${report.totalPremium},${report.conversionRate}%`);

  for (const [key, val] of Object.entries(report.byProduct)) {
    lines.push(`Product,${key},${val.quotes},${val.bound},${val.premium},${val.conversionRate}%`);
  }
  for (const [key, val] of Object.entries(report.byAgent)) {
    lines.push(`Agent,${key},${val.quotes},${val.bound},${val.premium},${val.conversionRate}%`);
  }
  for (const [key, val] of Object.entries(report.byRegion)) {
    lines.push(`Region,${key},${val.quotes},${val.bound},${val.premium},${val.conversionRate}%`);
  }

  return lines.join('\n');
}

function hasProperty<K extends string>(obj: object, key: K): obj is object & Record<K, unknown> {
  return key in obj;
}

function isUserWithRole(user: unknown): user is { email: string; role: Role } {
  if (typeof user !== 'object' || user === null) return false;
  if (!hasProperty(user, 'role') || !hasProperty(user, 'email')) return false;
  return typeof user.role === 'string' && typeof user.email === 'string';
}

function isRecordArray(value: unknown): value is Array<Record<string, unknown>> {
  if (!Array.isArray(value)) return false;
  return value.every(
    (item) => typeof item === 'object' && item !== null
  );
}

export async function GET(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    if (!isUserWithRole(session.user)) {
      logger.warn(`User object missing role property for user on reports endpoint`);
      return NextResponse.json({ error: 'Forbidden: insufficient permissions' }, { status: 403 });
    }

    const userRole = session.user.role;
    if (!ALLOWED_ROLES.includes(userRole)) {
      logger.warn(`Access denied for user ${session.user.email} with role ${userRole} on reports endpoint`);
      return NextResponse.json({ error: 'Forbidden: insufficient permissions' }, { status: 403 });
    }

    const { searchParams } = new URL(request.url);
    const filters = parseFilters(searchParams);
    const format = searchParams.get('format') ?? 'json';
    const where = buildWhereClause(filters);

    const records = await db.insuranceQuote.findMany({
      where,
      orderBy: { createdAt: 'asc' },
    });

    const normalizedRecords: Array<Record<string, unknown>> = isRecordArray(records)
      ? records
      : [];

    const report = aggregateRecords(normalizedRecords);

    logger.info(`Report generated by ${session.user.email}: ${report.totalQuotes} quotes, ${report.totalPoliciesBound} bound`, { filters });

    if (format === 'csv') {
      const csv = toCsv(report);
      return new NextResponse(csv, {
        status: 200,
        headers: {
          'Content-Type': 'text/csv; charset=utf-8',
          'Content-Disposition': `attachment; filename="insurance-report-${Date.now()}.csv"`,
        },
      });
    }

    return NextResponse.json({ success: true, data: report }, { status: 200 });
  } catch (error) {
    const err = error instanceof Error ? error : new Error(JSON.stringify(error));
    Sentry.captureException(err);
    logger.error('Failed to generate insurance report', {
      err,
      message: err.message,
      stack: err.stack,
    });

    return NextResponse.json(
      { error: 'Internal server error while generating report' },
      { status: 500 }
    );
  }
}

